<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); use Illuminate\Support\Str; foreach(\App\Models\UniteValeur::whereNull("slug")->get() as $uv) { $uv->slug = Str::slug($uv->nom . "-" . $uv->id); $uv->save(); echo "Slug updated for " . $uv->id . "\n"; }
